def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Check if field starts with a quote
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check for doubled quote or end of quoted field
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add single quote and skip both
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Next char must be comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        fields.append(''.join(field))
                        if i < len(line):
                            # Skip the comma
                            i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field - read until comma
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain quotes
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < len(line):
                # Skip the comma
                i += 1

    return fields

